def coordinateRegion {n N : ℕ} (S : ℝ) (q : Fin N → CoordinateCut n)
    (k : ℕ) (j : Fin n) : Set ℂ :=
  {ζ | |ζ.re| ≤ S ∧ |ζ.im| ≤ S ∧
    ∀ i : Fin N, k ≤ i.val → (q i).coordinate = j →
      ((q i).coefficient * ζ).re ≤ (q i).bound}

